<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>VITS — Services</title>
  <link rel="icon" href="<?php echo esc_url( $vits ); ?>/assets/logo.png">
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,400;0,9..40,500;0,9..40,600;0,9..40,700&display=swap" rel="stylesheet">
  <style>
    :root {
      --navy: #212146; --blue: #667EE5; --white: #fff;
      --gutter: clamp(20px, 5.38vw, 93px); --max: 1728px; --content: 1542px;
      --s: calc(min(100vw, 1728px) / 1728); /* 1 Figma px */
      --grid-img: url("data:image/svg+xml;base64,");
    }
    * { box-sizing: border-box; margin: 0; padding: 0; }
    html, body { overflow-x: hidden; }
    body { position: relative; font-family: "DM Sans", sans-serif; color: var(--navy); background: #fff; }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    .wrap { width: min(100%, var(--max)); margin: 0 auto; padding: 0 var(--gutter); }

    /* ---------- NAV (same as index.html) ---------- */
    header.nav { position: sticky; top: 0; z-index: 50; background: #fff; }
    .nav-inner { width: min(100%, var(--max)); margin: 0 auto; padding: 28px var(--gutter) 22px; display: flex; align-items: center; justify-content: space-between; gap: 24px; }
    .logo-img { height: 48px; width: auto; }
    nav.links { display: flex; align-items: center; gap: 42px; }
    nav.links a { display: inline-flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 500; letter-spacing: 1.6px; text-transform: uppercase; color: var(--navy); height: 51px; padding: 0 26px; border-radius: 999px; background: transparent; position: relative; transition: background .2s ease, color .2s ease; }
    nav.links a:not(.contact-btn):hover::after, nav.links a:not(.contact-btn):active::after, nav.links a:not(.contact-btn).active::after { content: ""; position: absolute; left: 26px; right: 26px; bottom: 12px; height: 1px; background: var(--navy); }
    nav.links a.contact-btn, nav.links a.contact-btn:hover { background: var(--navy); color: #fff; }
    nav.links a.contact-btn:active { background: #fff; color: var(--navy); box-shadow: inset 0 0 0 1px var(--navy); }
    .burger { display: none; flex-direction: column; gap: 5px; padding: 8px; }
    .burger span { width: 22px; height: 2px; background: var(--navy); border-radius: 2px; }

    /* ---------- BACKGROUND: one blurred gradient + grid tiles (Figma coordinates) ---------- */
    .bg-wrap { position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 0; }
    .bg-gradient { position: absolute; left: 0; width: 100%; top: calc(440 * var(--s)); height: calc(2502 * var(--s)); background: url("data:image/svg+xml;base64,") center top / 100% 100% no-repeat; }
    .bg-grid { position: absolute; left: 0; width: 100%; top: calc(1687 * var(--s)); height: calc(1203 * var(--s)); }
    .bg-grid i { position: absolute; left: 0; right: 0; height: calc(603 * var(--s)); background: var(--grid-img) left top / 100% auto no-repeat; }
    .bg-grid i:nth-child(1) { top: 0; }
    .bg-grid i:nth-child(2) { top: calc(600 * var(--s)); }
    .bg-grid i:nth-child(3) { display: none; }

    /* ---------- CONTENT ---------- */
    main { position: relative; z-index: 1; width: min(var(--content), calc(100% - 2 * var(--gutter))); margin: 0 auto; padding-top: calc(139 * var(--s)); }
    .page-title, .mid-title { font-size: calc(56 * var(--s)); line-height: 1.55; font-weight: 400; }
    .page-title { color: var(--blue); margin-bottom: calc(110 * var(--s)); }
    .mid-title { color: #fff; text-align: right; font-weight: 500; margin: calc(103 * var(--s)) 0 calc(105 * var(--s)); }
    .grid { display: grid; grid-template-columns: 1fr 1fr; column-gap: calc(76 * var(--s)); row-gap: calc(65 * var(--s)); }
    .card {
      min-height: calc(602 * var(--s)); padding: calc(50 * var(--s)) calc(40 * var(--s)) calc(40 * var(--s));
      border-radius: calc(40 * var(--s)); text-align: center;
      background: linear-gradient(145deg, rgba(255,255,255,.34), rgba(255,255,255,.12));
      border: 1px solid rgba(255,255,255,.5);
      -webkit-backdrop-filter: blur(20px); backdrop-filter: blur(20px);
      box-shadow: inset 0 1px 0 rgba(255,255,255,.55), 0 10px 40px rgba(60,80,150,.06);
    }
    .card .icon { width: calc(252 * var(--s)); height: calc(252 * var(--s)); margin: 0 auto; max-width: none; }
    .card h2 { min-height: calc(104 * var(--s)); margin-top: calc(24 * var(--s)); display: flex; align-items: center; justify-content: center; font-size: calc(34 * var(--s)); line-height: 1.5; font-weight: 500; }
    .card p { margin: calc(12 * var(--s)) auto 0; max-width: calc(480 * var(--s)); font-size: calc(20 * var(--s)); line-height: 1.5; font-weight: 400; }
    .grid + .mid-title + .grid { margin-bottom: 0; }

    /* ---------- CTA / FOOTER (copied from index.html) ---------- */
    .cta-section { position: relative; z-index: 1; margin-top: calc(110 * var(--s)); }
    .cta-section {
      position: relative;
      overflow: hidden;
      padding: 0 0 48px;
      scroll-margin-top: 110px;
      background:
        linear-gradient(180deg, #ffffff 0%, #ffffff 6%, rgba(255,255,255,.7) 16%, rgba(255,255,255,0) 38%),
        linear-gradient(115deg, #FA5304 0%, #c56b8a 22%, #2C75CF 48%, #d9785c 78%, #FA5304 100%);
    }
    .cta-blob {
      position: absolute;
      left: 50%;
      top: 8%;
      width: 140%;
      height: 110%;
      max-width: none;
      transform: translateX(-50%);
      pointer-events: none;
      z-index: 0;
      -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 22%, #000 100%);
      mask-image: linear-gradient(180deg, transparent 0%, #000 22%, #000 100%);
    }
    .cta-blob svg {
      width: 100%;
      height: 100%;
      max-width: none;
      display: block;
      filter: blur(48px);
    }
    .cta-grid {
      position: absolute;
      left: 50%;
      top: 18%;
      width: min(100%, 1728px);
      height: 603px;
      transform: translateX(-50%);
      object-fit: fill;
      opacity: .62;
      pointer-events: none;
      z-index: 0;
      -webkit-mask-image: linear-gradient(180deg, transparent 0%, #000 24%);
      mask-image: linear-gradient(180deg, transparent 0%, #000 24%);
    }
    .cta-heading {
      position: relative;
      z-index: 1;
      width: min(100%, var(--max));
      margin: 0 auto 16px;
      padding: 140px var(--gutter) 0;
      text-align: center;
      font-size: clamp(32px, 4.63vw, 80px);
      font-weight: 600;
      letter-spacing: 0;
      line-height: 1.05;
      color: rgba(255, 255, 255, 0.78);
    }
    .footer-card {
      position: relative;
      z-index: 1;
    }
    .footer-inner {
      background: rgba(255,255,255,.2);
      border-radius: 29px;
      min-height: 520px;
      padding: 64px 68px 56px;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 40px;
    }
    .footer-logo { height: 86px; width: auto; margin-bottom: 36px; }
    .footer-label {
      font-size: 32px;
