      line-height: 1.45;
      font-weight: 500;
    }
    .contact-line { display: block; margin-top: 16px; }
    .footer-social {
      display: flex;
      align-items: center;
      gap: 8px;
      margin-top: 28px;
    }
    .footer-social a {
      width: 53px;
      height: 53px;
      display: grid;
      place-items: center;
      border: none;
      background: none;
    }
    .footer-social a img {
      width: 53px;
      height: 53px;
    }
    .footer-right {
      display: flex;
      flex-direction: column;
      align-items: flex-end;
      text-align: right;
      justify-content: flex-end;
      padding-bottom: 8px;
    }
    .footer-right h3 {
      font-size: clamp(32px, 3.3vw, 56px);
      font-weight: 600;
      color: rgba(255,255,255,.58);
      letter-spacing: 0;
      margin-bottom: 16px;
    }
    .footer-right p {
      width: min(465px, 100%);
      font-family: "DM Sans", sans-serif;
      font-size: 32px;
      font-weight: 400;
      font-style: normal;
      color: #212146;
      line-height: 1;
      letter-spacing: 0;
      text-align: right;
      margin-bottom: 36px;
    }
    .footer-actions {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 8px;
    }
    .footer-inner .footer-actions a,
    .footer-inner .footer-actions a:link,
    .footer-inner .footer-actions a:visited,
    .footer-inner .footer-actions a:any-link {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      height: 51px;
      padding: 0 22px;
      border-radius: 999px;
      font-size: 14px;
      font-weight: 600;
      letter-spacing: 1.8px;
      text-transform: uppercase;
      color: #212146;
      -webkit-text-fill-color: #212146;
      background: transparent;
      transition: background .2s ease, color .2s ease, -webkit-text-fill-color .2s ease;
    }
    .footer-inner .footer-actions a:hover {
      background: var(--navy);
      color: #ffffff;
      -webkit-text-fill-color: #ffffff;
    }

    @media (max-width: 860px) {
      nav.links { position: fixed; inset: 76px 16px auto; background: #fff; flex-direction: column; align-items: flex-start; gap: 18px; padding: 24px; border-radius: 16px; box-shadow: 0 16px 40px rgba(33,33,70,.12); transform: translateY(-12px); opacity: 0; pointer-events: none; transition: .25s ease; }
      nav.links.open { opacity: 1; pointer-events: auto; transform: none; }
      .burger { display: flex; }
      main { padding-top: 48px; }
      .page-title, .mid-title { font-size: clamp(30px, 8vw, 40px); line-height: 1.25; }
      .page-title { margin-bottom: 40px; }
      .mid-title { text-align: left; margin: 56px 0 40px; }
      .grid { grid-template-columns: 1fr; gap: 20px; }
      .card { min-height: 0; padding: 32px 24px; border-radius: 28px; }
      .card .icon { width: 150px; height: 150px; }
      .card h2 { min-height: 0; margin-top: 16px; font-size: 24px; }
      .card p { margin-top: 10px; max-width: none; font-size: 16px; }
      .bg-gradient { top: 240px; height: 2600px; }
      .bg-grid { top: 400px; height: 2300px; background: var(--grid-img) 30% 0 / 1200px auto repeat-y; }
      .bg-grid i { display: none; }
      .cta-section { margin-top: 60px; }
      .footer-inner { grid-template-columns: 1fr; min-height: 0; padding: 40px 28px; }
.footer-right { align-items: flex-start; text-align: left; }
    }
  </style>
</head>
